before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
)


func main() {
    values := make(chan int, 2)
    values <- 3
    values <- 4
    close(values)
    total := 0
    for value := range values { total += value }
    fmt.Println(total)
}
```

